import{_ as t,o as d,c as a,a0 as o}from"./chunks/framework.BENn8n5I.js";const m=JSON.parse('{"title":"Allowed commit prefixes","description":"","frontmatter":{},"headers":[],"relativePath":"prefixes.md","filePath":"prefixes.md"}'),r={name:"prefixes.md"};function c(s,e,i,n,p,h){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="allowed-commit-prefixes" tabindex="-1">Allowed commit prefixes <a class="header-anchor" href="#allowed-commit-prefixes" aria-label="Permalink to &quot;Allowed commit prefixes&quot;">​</a></h1><p>Use one of these lowercase prefixes at the start of each commit message. These are the prefixes accepted by gha-commit&#39;s validator and supported by its tagging workflow.</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Purpose</th><th>Version bump</th></tr></thead><tbody><tr><td><code>epic</code></td><td>Large product milestone or coordinated feature set</td><td>Major</td></tr><tr><td><code>major</code></td><td>Explicitly mark a major release change</td><td>Major</td></tr><tr><td><code>feat</code></td><td>Add or extend user-visible functionality</td><td>Minor</td></tr><tr><td><code>fix</code></td><td>Correct a bug</td><td>Patch</td></tr><tr><td><code>build</code></td><td>Change build system, dependencies, or packaging</td><td>Patch</td></tr><tr><td><code>chore</code></td><td>Routine maintenance that does not change product behavior</td><td>Patch</td></tr><tr><td><code>perf</code></td><td>Improve performance</td><td>Patch</td></tr><tr><td><code>refactor</code></td><td>Restructure code without changing behavior</td><td>Patch</td></tr><tr><td><code>revert</code></td><td>Revert a previous change</td><td>Patch</td></tr><tr><td><code>style</code></td><td>Formatting or style-only change</td><td>Patch</td></tr><tr><td><code>cicd</code></td><td>Change CI/CD workflows or deployment configuration</td><td>Patch</td></tr><tr><td><code>docs</code></td><td>Documentation-only change</td><td>No tag</td></tr><tr><td><code>test</code></td><td>Add or update tests</td><td>No tag</td></tr></tbody></table><p>The tagger also skips <code>chore(release)</code> commits, which are commonly generated by release automation. A breaking-change marker overrides the normal bump: append <code>!</code> after the prefix or scope to request a major bump. For example, <code>fix(api)!: change the error response</code> is a major change despite the <code>fix</code> prefix. See <a href="./tagging.html">Bump version tag</a> for footer syntax and details.</p><h2 id="header-examples" tabindex="-1">Header examples <a class="header-anchor" href="#header-examples" aria-label="Permalink to &quot;Header examples&quot;">​</a></h2><p>The scope is optional, but when present it must not be empty:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feat: add keyboard navigation</span></span>
<span class="line"><span>fix(router): preserve query parameters</span></span>
<span class="line"><span>build(deps)!: drop support for the old runtime</span></span></code></pre></div><p>The third example creates a major bump because it includes <code>!</code>. A breaking change can also be declared with a <code>BREAKING CHANGE:</code> or <code>BREAKING-CHANGE:</code> footer; those footer forms are described in the <a href="./tagging.html">version tagging guide</a>.</p>`,8)])])}const g=t(r,[["render",c]]);export{m as __pageData,g as default};
